require_once __DIR__ . '/partials.php';
require_once __DIR__ . '/api/duffel.php';
function fr_h(string $v): string { return htmlspecialchars($v, ENT_QUOTES, 'UTF-8'); }
function fr_valid_date(string $date): bool {$d=DateTime::createFromFormat('Y-m-d',$date);return $d&&$d->format('Y-m-d')===$date;}
function fr_time(?string $dt): string {$t=$dt?strtotime($dt):false;return $t?date('H:i',$t):'';}
function fr_day(?string $dt): string {$t=$dt?strtotime($dt):false;return $t?date('D, d M',$t):'';}
function fr_minutes(?string $duration): int {if(!$duration)return 0;try{$iv=new DateInterval($duration);return($iv->d*1440)+($iv->h*60)+$iv->i;}catch(Throwable $e){return 0;}}
function fr_duration(?string $duration): string {$m=fr_minutes($duration);if($m<=0)return'';$h=intdiv($m,60);$r=$m%60;return($h?$h.'h ':'').($r?$r.'m':'');}
function fr_offer_duration(array $offer): int {$total=0;foreach(($offer['slices']??[])as$slice)$total+=fr_minutes($slice['duration']??null);return$total;}
function fr_max_stops(array $offer): int {$max=0;foreach(($offer['slices']??[])as$slice)$max=max($max,max(0,count($slice['segments']??[])-1));return$max;}
function fr_airline(array $offer): string {if(!empty($offer['owner']['name']))return(string)$offer['owner']['name'];foreach(($offer['slices']??[])as$slice)foreach(($slice['segments']??[])as$segment)if(!empty($segment['marketing_carrier']['name']))return(string)$segment['marketing_carrier']['name'];return'Airline';}
function fr_logo(array $offer): string {return(string)($offer['owner']['logo_symbol_url']??$offer['owner']['logo_lockup_url']??'');}
function fr_operating(array $offer): array {$names=[];foreach(($offer['slices']??[])as$slice)foreach(($slice['segments']??[])as$segment){$name=trim((string)($segment['operating_carrier']['name']??''));if($name!=='')$names[]=$name;}return array_values(array_unique($names));}
function fr_baggage(array $offer): array {$checked=0;$carry=0;foreach(($offer['slices']??[])as$slice)foreach(($slice['segments']??[])as$segment)foreach(($segment['passengers']??[])as$passenger)foreach(($passenger['baggages']??[])as$bag){$type=strtolower((string)($bag['type']??''));$qty=(int)($bag['quantity']??0);if($type==='checked')$checked=max($checked,$qty);if(in_array($type,['carry_on','cabin'],true))$carry=max($carry,$qty);}return['checked'=>$checked,'carry'=>$carry];}
function fr_hold(array $offer): bool {return(($offer['payment_requirements']['requires_instant_payment']??true)===false);}
function fr_stop_airports(array $slice): array {$segments=$slice['segments']??[];$out=[];for($i=0;$i<count($segments)-1;$i++){$code=$segments[$i]['destination']['iata_code']??'';if($code)$out[]=$code;}return$out;}
function fr_flights(array $slice): string {$out=[];foreach(($slice['segments']??[])as$s){$code=(string)($s['marketing_carrier']['iata_code']??'');$num=(string)($s['marketing_carrier_flight_number']??'');if($code||$num)$out[]=trim($code.' '.$num);}return implode(' · ',$out);}
$criteria=['trip_type'=>(($_GET['trip_type']??'round')==='oneway'?'oneway':'round'),'origin'=>strtoupper(trim($_GET['origin']??'')),'destination'=>strtoupper(trim($_GET['destination']??'')),'departure'=>trim($_GET['departure']??''),'return_date'=>trim($_GET['return_date']??''),'adults'=>max(1,min(9,(int)($_GET['adults']??1))),'children'=>max(0,min(8,(int)($_GET['children']??0))),'infants'=>max(0,min(9,(int)($_GET['infants']??0))),'cabin'=>trim($_GET['cabin']??'economy')];
$allowedCabins=['economy','premium_economy','business','first'];$error='';$offers=[];
if(!preg_match('/^[A-Z]{3}$/',$criteria['origin']))$error='Invalid origin airport.';elseif(!preg_match('/^[A-Z]{3}$/',$criteria['destination']))$error='Invalid destination airport.';elseif($criteria['origin']===$criteria['destination'])$error='Origin and destination cannot be the same.';elseif(!fr_valid_date($criteria['departure']))$error='Invalid departure date.';elseif($criteria['departure']<date('Y-m-d'))$error='Departure date cannot be in the past.';elseif($criteria['trip_type']==='round'&&!fr_valid_date($criteria['return_date']))$error='Invalid return date.';elseif($criteria['trip_type']==='round'&&$criteria['return_date']<$criteria['departure'])$error='Return date cannot be before departure.';elseif($criteria['infants']>$criteria['adults'])$error='Infants cannot exceed adults.';elseif(!in_array($criteria['cabin'],$allowedCabins,true))$error='Invalid cabin class.';else{$api=mt_duffel_search($criteria);if(!$api['ok']){$error=$api['error'];error_log('FLIGHT RESULTS DUFFEL | HTTP '.$api['status'].' | '.json_encode($api['data']));}else{$offers=$api['data']['data']['offers']??[];if(!is_array($offers))$offers=[];$offers=array_slice($offers,0,50);}}
$airlines=[];foreach($offers as$o)$airlines[]=fr_airline($o);$airlines=array_values(array_unique($airlines));sort($airlines);site_header('Flight Results');
?>
