<?php foreach(($offer['slices']??[])as$slice):$segments=$slice['segments']??[];$first=$segments[0]??[];$last=$segments?$segments[count($segments)-1]:[];$from=$first['origin']['iata_code']??'';$to=$last['destination']['iata_code']??'';$dep=$first['departing_at']??'';$arr=$last['arriving_at']??'';$sliceStops=max(0,count($segments)-1);$stopAirports=fr_stop_airports($slice);?><div class="fr-slice"><div class="fr-route"><div class="fr-point"><strong><?=fr_h(fr_time($dep))?></strong><span><?=fr_h($from)?></span><small><?=fr_h(fr_day($dep))?></small></div><div><div class="fr-line"></div><div class="fr-meta"><?=fr_h(fr_duration($slice['duration']??null))?> · <?=$sliceStops===0?'Direct':($sliceStops===1?'1 stop':$sliceStops.' stops')?><?php if($stopAirports):?> · <span class="fr-stop"><?=fr_h(implode(', ',$stopAirports))?></span><?php endif;?></div><div class="fr-flightnums"><?=fr_h(fr_flights($slice))?></div></div><div class="fr-point end"><strong><?=fr_h(fr_time($arr))?></strong><span><?=fr_h($to)?></span><small><?=fr_h(fr_day($arr))?></small></div></div></div><?php endforeach;?></div><div class="fr-price"><small>Total fare</small><strong><?=fr_h($currency)?> <?=number_format($amount,2)?></strong><div class="per">for all travellers</div><a class="fr-select" href="flight-fare.php?offer_id=<?=urlencode($offerId)?>">Select</a></div></div><div class="fr-bagpanel"><div class="fr-bagitem <?=$bag['checked']>0?'good':''?>"><small>Checked baggage</small><strong><?=$bag['checked']>0?$bag['checked'].' piece'.($bag['checked']>1?'s':'').' included':'Not shown as included'?></strong></div><div class="fr-bagitem <?=$bag['carry']>0?'good':'note'?>"><small>Cabin baggage</small><strong><?=$bag['carry']>0?$bag['carry'].' piece'.($bag['carry']>1?'s':'').' included':'Confirm on fare details / airline rules'?></strong></div><div class="fr-bagitem note"><small>Extra baggage</small><strong>Available options are checked after selecting the fare</strong></div></div></article><?php endforeach;?></div></main></div><?php endif;?></div></section>
<script>document.addEventListener('DOMContentLoaded',function(){const wrap=document.getElementById('cards');if(!wrap)return;const cards=[...wrap.querySelectorAll('.fr-card')],count=document.getElementById('visibleCount');function applyFilters(){const stop=document.querySelector('input[name="stopFilter"]:checked')?.value||'any',airline=document.getElementById('airlineFilter').value,bag=document.getElementById('bagFilter').checked,hold=document.getElementById('holdFilter').checked,text=document.getElementById('textFilter').value.trim().toLowerCase();let n=0;cards.forEach(card=>{let ok=true,stops=parseInt(card.dataset.stops,10);if(stop!=='any'&&stops>parseInt(stop,10))ok=false;if(airline&&card.dataset.airline!==airline)ok=false;if(bag&&card.dataset.bag!=='1')ok=false;if(hold&&card.dataset.hold!=='1')ok=false;if(text&&!card.dataset.search.includes(text))ok=false;card.style.display=ok?'':'none';if(ok)n++});count.textContent=n}document.querySelectorAll('input[name="stopFilter"]').forEach(x=>x.addEventListener('change',applyFilters));document.getElementById('airlineFilter').addEventListener('change',applyFilters);document.getElementById('bagFilter').addEventListener('change',applyFilters);document.getElementById('holdFilter').addEventListener('change',applyFilters);document.getElementById('textFilter').addEventListener('input',applyFilters);document.getElementById('resetFilters').addEventListener('click',function(){document.querySelector('input[name="stopFilter"][value="any"]').checked=true;document.getElementById('airlineFilter').value='';document.getElementById('bagFilter').checked=false;document.getElementById('holdFilter').checked=false;document.getElementById('textFilter').value='';applyFilters()});function sortCards(type){[...cards].sort((a,b)=>{const key=type==='price'?'price':(type==='duration'?'duration':'best');return parseFloat(a.dataset[key])-parseFloat(b.dataset[key])}).forEach(card=>wrap.appendChild(card));document.querySelectorAll('.fr-sort').forEach(btn=>btn.classList.toggle('active',btn.dataset.sort===type))}document.querySelectorAll('.fr-sort').forEach(btn=>btn.addEventListener('click',()=>sortCards(btn.dataset.sort)));sortCards('best')});</script>
